// Bearer <token de sessao> no cabecalho; o token FCM vem no corpo.
// A mesma funcao atende as duas rotas: a URL diz se e para remover.
const auth = (msg.req && msg.req.headers && msg.req.headers.authorization) || '';
const sess = auth.replace(/^Bearer\s+/i, '').trim();
const fcm = String((msg.payload || {}).fcm_token || '').trim();
if (!sess || !fcm) {
    msg.statusCode = 400;
    msg.payload = { error: 'missing' };
    return [null, msg];
}
const remover = String(msg.req.url || '').indexOf('unregister') >= 0;
msg.params = [sess, fcm, remover];
return [msg, null];

const row = (msg.payload && msg.payload[0]) || {};
if (row.status === 'ok') {
    msg.statusCode = 200;
    msg.payload = { ok: true };
} else {
    msg.statusCode = 401;
    msg.payload = { error: row.status || 'unauthorized' };
}
return msg;

// Preferencia de notificacao DESTE celular. A identidade do aparelho e o
// proprio token FCM -- ja e a chave primaria de push_tokens, nao foi preciso
// inventar um id de celular.
const auth = (msg.req && msg.req.headers && msg.req.headers.authorization) || '';
const sess = auth.replace(/^Bearer\s+/i, '').trim();
const body = msg.payload || {};
const fcm = String(body.fcm_token || '').trim();
const notify = body.notify;
if (!sess || !fcm || typeof notify !== 'object' || notify === null) {
    msg.statusCode = 400;
    msg.payload = { error: 'missing' };
    return [null, msg];
}
// So as chaves conhecidas, e so booleano: o corpo vem do celular e vai para
// uma coluna jsonb, entao nada de gravar o que chegar.
const permitidas = ['motion', 'camera_offline', 'tvbox_offline'];
const limpo = {};
for (const k of permitidas) {
    if (typeof notify[k] === 'boolean') limpo[k] = notify[k];
}
msg.params = [sess, fcm, JSON.stringify(limpo)];
return [msg, null];

// GET nao tem corpo: o token FCM vem na query string.
const auth = (msg.req && msg.req.headers && msg.req.headers.authorization) || '';
const sess = auth.replace(/^Bearer\s+/i, '').trim();
const fcm = String(((msg.req && msg.req.query) || {}).fcm_token || '').trim();
if (!sess || !fcm) {
    msg.statusCode = 400;
    msg.payload = { error: 'missing' };
    return [null, msg];
}
msg.params = [sess, fcm];
return [msg, null];

const row = (msg.payload && msg.payload[0]) || {};
if (row.status === 'ok') {
    msg.statusCode = 200;
    msg.payload = { ok: true };
} else if (row.status === 'not_registered') {
    // O celular ainda nao mandou o token FCM. Nao e erro de autenticacao: o
    // app registra o token e tenta de novo.
    msg.statusCode = 409;
    msg.payload = { error: 'not_registered' };
} else {
    msg.statusCode = 401;
    msg.payload = { error: row.status || 'unauthorized' };
}
return msg;

const row = (msg.payload && msg.payload[0]) || {};
const r = row.push_notify || {};
if (r.status === 'ok') {
    msg.statusCode = 200;
    // Chave ausente significa "quer receber" -- o padrao e tudo ligado, e o
    // app so precisa saber o que foi explicitamente desligado.
    msg.payload = { registered: !!r.registered, notify: r.notify || {} };
} else {
    msg.statusCode = 401;
    msg.payload = { error: (r && r.status) || 'unauthorized' };
}
return msg;
